\begin{thm}
THEOREM 2.5. The intersection of an arbitrary collection of convex cones is a convex cone.
\end{thm}

proof:
\begin{proof}
\textbf{PROOF.} Elementary.
\end{proof}

content:
\begin{cor}
COROLLARY 2.5.1. Let \( b_i \in R^n \) for \( i \in I \), where \( I \) is an arbitrary index set. Then

\[
K = \{x \in R^n \mid \langle x, b_i \rangle \leq 0, i \in I\}
\]

is a convex cone.
\end{cor}

\begin{thm}
Theorem 2.6. A subset of \(R^n\) is a convex cone if and only if it is closed under addition and positive scalar multiplication.
\end{thm}

proof:
\begin{proof}
Let \(K\) be a cone. Let \(x \in K\) and \(y \in K\). If \(K\) is convex, the vector \(z = (1/2)(x + y)\) belongs to \(K\), and hence \(x + y = 2z \in K\). On the other hand, if \(K\) is closed under addition, and if \(0 < \lambda < 1\), the vectors \((1 - \lambda)x\) and \(\lambda y\) belong to \(K\), and hence \((1 - \lambda)x + \lambda y \in K\). Thus \(K\) is convex if and only if it is closed under addition. \(\|\)
\end{proof}

content:
\begin{cor}
Corollary 2.6.1. A subset of \(R^n\) is a convex cone if and only if it contains all the positive linear combinations of its elements (i.e. linear combinations \(\lambda_1 x_1 + \cdots + \lambda_m x_m\) in which the coefficients are all positive).
\end{cor}

\begin{cor}
Corollary 2.6.2. Let \(S\) be an arbitrary subset of \(R^n\), and let \(K\) be the set of all positive linear combinations of \(S\). Then \(K\) is the smallest convex cone which includes \(S\).
\end{cor}

proof:
\begin{proof}
Clearly \(K\) is closed under addition and positive scalar multiplication, and \(K \supset S\). Every convex cone including \(S\) must, on the other hand, include \(K\). \(\|\)
\end{proof}

