\begin{thm}
Theorem 3.1. If \( C_1 \) and \( C_2 \) are convex sets in \( R^n \), then so is their sum \( C_1 + C_2 \), where

\[
C_1 + C_2 = \{x_1 + x_2 \mid x_1 \in C_1, x_2 \in C_2\}.
\]
\end{thm}

\begin{thm}
Theorem 3.2. If \( C \) is a convex set and \( \lambda_1 \geq 0, \lambda_2 \geq 0 \), then

\[
(\lambda_1 + \lambda_2)C = \lambda_1 C + \lambda_2 C.
\]
\end{thm}

proof:
\begin{proof}
Proof. The inclusion \( \subseteq \) would be true whether \( C \) were convex or not.
\end{proof}

